<?php
// Original customers design with customers who ordered from this station.
use App\Services\Workspace;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->customers(''));
$rows = $live['customers'] ?? [];
$type = fn($t) => (string) count(array_filter($rows, fn($c) => $c['classification'] === $t));
$phone = static fn (?string $p): string => $p && preg_match('/^\+63(9\d{2})(\d{3})(\d{4})$/', $p, $m) ? '0'.$m[1].' '.$m[2].' '.$m[3] : (string) $p;
?>
<?= U::heading('Customers','Customers who order from '.$info['caption'].'.',U::btn('Export CSV','','secondary','download',['data-export'=>'station-customers'])) ?>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Customers',(string)count($rows),'users','blue','Ordered from this station','All') ?><?= U::stat('Households',$type('household'),'home','green','Family deliveries','Homes') ?><?= U::stat('Institutions',$type('institution'),'store','violet','Schools and offices','Groups') ?><?= U::stat('Total orders',(string)array_sum(array_column($rows,'orders')),'orders','amber','Across all customers','Orders') ?></div>
<section class="panel p-4 md:p-5"><div class="mb-4 max-w-lg"><?= U::field('Search customers','customer-search','','search',['icon'=>'search','data-search'=>'station-customers','placeholder'=>'Name, barangay or phone']) ?></div><div class="overflow-x-auto"><table class="data-table" id="station-customers"><thead><tr><th>Customer</th><th>Barangay</th><th>Type</th><th>Phone</th><th>Orders</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i=>$c): $label = $c['classification'] === 'institution' ? 'Institution' : 'Household'; ?><tr data-search-row><td><div class="flex items-center gap-3"><span class="title-icon"><?= U::icon($label==='Institution'?'store':'home','size-4.5') ?></span><strong><?= U::e($c['name'] ?? 'Customer') ?></strong></div></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('pin','size-4 text-water') ?><?= U::e($c['barangay'] ?? 'Pickup') ?></span></td><td><?= U::badge($label,$label==='Institution'?'blue':'gray') ?></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('phone','size-4 text-muted') ?><?= U::e($phone($c['phone'] ?? '')) ?></span></td><td class="font-semibold"><?= (int) $c['orders'] ?></td><td><div class="flex flex-wrap gap-2"><?= U::btn('Details','','secondary','eye',['class'=>'btn-sm','data-dialog-open'=>'customer-'.$i]).U::btn('Message','/station-admin/messages?customer='.$c['customer_id'],'ghost','message',['class'=>'btn-sm']) ?></div></td></tr><?php endforeach ?></tbody></table><p <?= $rows === [] ? '' : 'hidden' ?> data-empty class="p-5 muted"><?= isset($live['error']) ? U::e($live['error']) : ($rows === [] ? 'No customer has ordered from this station yet.' : 'No matching customers.') ?></p></div></section>
<?php foreach($rows as $i=>$c): ?><dialog id="customer-<?= $i ?>" class="w-full max-w-lg rounded-xl border border-line p-6 text-ink"><?= U::title($c['name'] ?? 'Customer','user') ?><p class="mt-2 text-sm text-muted"><?= U::e($c['classification'] === 'institution' ? 'Institution' : 'Household') ?>, <?= U::e($c['barangay'] ?? 'Pickup') ?>, Hamtic</p><dl class="my-4 space-y-1.5 text-sm"><?php foreach ([['phone','Mobile number',$phone($c['phone'] ?? '')],['orders','Orders at this station',(string) $c['orders']],['check','Completed',(string) $c['completed']],['credit','Spent here',S::pesos($c['total_spent_centavos'])],['clock','Last order',S::time($c['last_order_at'], 'M j, Y')]] as [$icon,$dt,$dd]): ?><div class="flex items-center justify-between rounded-lg bg-mist px-3 py-2"><dt class="flex items-center gap-2 text-muted"><?= U::icon($icon,'size-4 text-water') ?><?= U::e($dt) ?></dt><dd class="font-medium"><?= U::e($dd) ?></dd></div><?php endforeach ?></dl>
<?= F::open('/station-admin/customers/classify', ['customer_id' => $c['customer_id'], 'expected_version' => (string) ($c['version'] ?? '')], ['class' => 'mb-4 flex items-end gap-2']) ?><div class="flex-1"><?= U::select('Customer type','classification',['household'=>'Household','institution'=>'Institution'],$c['classification'],['id'=>'class-'.$i]) ?></div><?= U::btn('Save','','secondary','check',['type'=>'submit']) ?></form>
<?= U::btn('Close','','secondary','close',['data-dialog-close'=>true]) ?></dialog><?php endforeach ?>
